/**
 * Personal project mutes: one row per member per project.
 */
import { and, asc, eq } from "drizzle-orm";
import { getDb, projectMutes } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { brandId } from "./_mappers";
import { orgPredicate } from "./base-repository";
import type { OrgId, ProjectId, UserId } from "@/types/common";

/** Records a mute. A second mute of the same project is a no-op. */
export async function muteProject(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .insert(projectMutes)
    .values({
      orgId,
      userId,
      projectId,
      createdAt: toIsoTimestamp(new Date()),
    })
    .onConflictDoNothing({
      target: [projectMutes.orgId, projectMutes.userId, projectMutes.projectId],
    })
    .run();
}

/** Lifts a mute. Unmuting a project that was not muted is a no-op. */
export async function unmuteProject(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .delete(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
        eq(projectMutes.projectId, projectId),
      ),
    )
    .run();
}

/** Projects `userId` has muted inside the org, in stable project-id order. */
export async function listMutedProjectIds(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ProjectId[]> {
  const rows = getDb()
    .select({ projectId: projectMutes.projectId })
    .from(projectMutes)
    .where(
      and(orgPredicate(projectMutes.orgId, orgId), eq(projectMutes.userId, userId)),
    )
    .orderBy(asc(projectMutes.projectId))
    .all();

  return rows.map((row) => brandId<ProjectId>(row.projectId));
}

/** Members of the org who have muted `projectId`. */
export async function listMutingUserIds(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly UserId[]> {
  const rows = getDb()
    .select({ userId: projectMutes.userId })
    .from(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.projectId, projectId),
      ),
    )
    .all();

  return rows.map((row) => brandId<UserId>(row.userId));
}

