/**
 * A muted recipient keeps their preference channels except `email`. Personal
 * kinds with nothing left are not created; the caller drops other kinds first.
 */
function channelsForRecipient(
  channels: readonly NotificationChannel[],
  muted: boolean,
): readonly NotificationChannel[] {
  if (!muted) return channels;
  return channels.filter((channel) => channel !== "email");
}

