import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import { NotFoundError } from "@/server/services/_support";
import { buildDigest } from "@/server/services/digest-service";
import {
  listMutedProjectIds,
  muteProject,
  notify,
  unmuteProject,
} from "@/server/services/notification-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IsoTimestamp, ProjectId } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("mute-check", "growth");
});

afterAll(() => cleanup());

describe("mute behavior", () => {
  it("mutes idempotently and only for the actor", async () => {
    await muteProject(tenant.actors.member, tenant.org.id, tenant.project.id);
    await muteProject(tenant.actors.member, tenant.org.id, tenant.project.id);
    expect(await listMutedProjectIds(tenant.actors.member, tenant.org.id)).toEqual([
      tenant.project.id,
    ]);
    expect(await listMutedProjectIds(tenant.actors.admin, tenant.org.id)).toEqual([]);

    await unmuteProject(tenant.actors.member, tenant.org.id, tenant.project.id);
    await unmuteProject(tenant.actors.member, tenant.org.id, tenant.project.id);
    expect(await listMutedProjectIds(tenant.actors.member, tenant.org.id)).toEqual([]);
  });

  it("guards like reading a project", async () => {
    const other = await createTenant("mute-other", "growth");
    await expect(
      muteProject(other.actors.owner, tenant.org.id, tenant.project.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      unmuteProject(other.actors.owner, tenant.org.id, tenant.project.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      muteProject(
        tenant.actors.member,
        tenant.org.id,
        "01ARZ3NDEKTSV4RRFFQ69G5FAV" as ProjectId,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      listMutedProjectIds(other.actors.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    expect(PermissionDeniedError).toBeTruthy();
  });

  it("drops non-personal, strips email from personal, and filters the digest", async () => {
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      kind: "issue_overdue",
      inApp: false,
      email: true,
      digestOnly: false,
    });

    await muteProject(tenant.actors.admin, tenant.org.id, tenant.project.id);
    await muteProject(tenant.actors.viewer, tenant.org.id, tenant.project.id);

    const created = await notify(
      tenant.org.id,
      "comment_created",
      [tenant.userIds.admin, tenant.userIds.viewer],
      {
        title: "comment",
        body: "body",
        href: "/issues/1",
        actorId: tenant.userIds.member,
        projectId: tenant.project.id,
      },
    );
    expect(created.map((row) => row.recipientId)).toEqual([]);

    const assigned = await notify(
      tenant.org.id,
      "issue_assigned",
      [tenant.userIds.admin],
      {
        title: "assigned",
        body: "body",
        href: "/issues/1",
        actorId: null,
        projectId: tenant.project.id,
      },
    );
    expect(assigned).toHaveLength(1);
    expect(assigned[0]?.channels).toEqual(["in_app"]);

    const overdue = await notify(
      tenant.org.id,
      "issue_overdue",
      [tenant.userIds.viewer],
      {
        title: "overdue",
        body: "body",
        href: "/issues/1",
        actorId: null,
        projectId: tenant.project.id,
      },
    );
    expect(overdue).toHaveLength(0);

    const joined = await notify(
      tenant.org.id,
      "member_joined",
      [tenant.userIds.admin],
      {
        title: "joined",
        body: "body",
        href: "/settings/members",
        actorId: null,
      },
    );
    expect(joined).toHaveLength(1);
    expect(joined[0]?.channels).toEqual(["in_app", "email"]);
    expect(joined[0]?.projectId).toBeNull();

    await notificationRepo.insertNotification(tenant.org.id, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      kind: "comment_created",
      title: "before mute",
      body: "before",
      href: "/issues/1",
      actorId: null,
      projectId: tenant.project.id,
      channels: ["email"],
    });
    await notificationRepo.insertNotification(tenant.org.id, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      kind: "member_joined",
      title: "org level",
      body: "org",
      href: "/settings/members",
      actorId: null,
      channels: ["email"],
    });
    await muteProject(tenant.actors.member, tenant.org.id, tenant.project.id);

    const windowEnd = new Date(Date.now() + 60_000).toISOString() as IsoTimestamp;
    const windowStart = new Date(Date.now() - 86_400_000).toISOString() as IsoTimestamp;
    const mutedBundle = await buildDigest(
      tenant.org.id,
      tenant.userIds.member,
      windowStart,
      windowEnd,
    );
    expect(mutedBundle?.entries.map((entry) => entry.title)).toEqual(["org level"]);

    const unread = await notificationRepo.listUnreadSince(
      tenant.org.id,
      tenant.userIds.member,
      windowStart,
    );
    expect(unread.some((row) => row.title === "before mute" && row.readAt === null)).toBe(
      true,
    );

    await unmuteProject(tenant.actors.member, tenant.org.id, tenant.project.id);
    const openBundle = await buildDigest(
      tenant.org.id,
      tenant.userIds.member,
      windowStart,
      windowEnd,
    );
    expect(openBundle?.entries.map((entry) => entry.title).sort()).toEqual([
      "before mute",
      "org level",
    ]);
  });
});

